class VtableBase {
public:
    // Virtual functions trigger vtable creation
    virtual void func1() = 0;
    virtual void func2() { /* Base impl */ }
    virtual ~VtableBase() = default;
};

class VtableDerived : public VtableBase {
public:
    // Overrides map to new pointers in Derived's vtable
    void func1() override { /* D1 */ }
    void func2() override { /* D2 */ }
};

// Object p contains a vptr pointing to VtableDerived's static array
VtableBase* p = new VtableDerived();
p->func1(); // Runtime dispatch via p->vptr[0]
delete p;
